WITH flagged AS (SELECT *, CASE WHEN LAG(started_at) OVER (PARTITION BY customer_id ORDER BY started_at ASC, id ASC) IS NULL OR started_at > LAG(started_at) OVER (PARTITION BY customer_id ORDER BY started_at ASC, id ASC) + INTERVAL '90' DAY THEN 1 ELSE 0 END AS session_start_flag FROM sessions), islands AS (SELECT *, SUM(session_start_flag) OVER (PARTITION BY customer_id ORDER BY started_at ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM flagged) SELECT id, customer_id, browser, started_at, country, burst_id, CASE WHEN country RLIKE '^(TH|US)$' THEN 'GROUP_A' WHEN country RLIKE '^(SG|JP)$' THEN 'PRIORITY' ELSE 'OTHER_ZONE' END AS country_zone FROM islands;
